import {test} from 'node:test';
import assert from 'node:assert/strict';
import {withRetry} from '../src/retry.mjs';

test('hidden check', async () => {
  const delays = [];
  await assert.rejects(withRetry(async () => { throw Object.assign(Error('x'), {retryable: true}); }, {retries: 5, sleep: async ms => delays.push(ms)}));
  assert.deepEqual(delays, [100, 200, 400, 800, 1000]);
});
